  const streetLink=p=>streetURL(p)?`<a href="${esc(streetURL(p))}" target="_blank" rel="noopener" title="가장 가까운 공개 파노라마를 새 창에서 열기. 사진이 없으면 구글 지도에서 주변 위치로 옮겨줘.">주변 로드뷰</a>`:'';
