  function hotelCard(h){const on=state.hotel===h.id;return `<article class="hotel-card ${on?'selected':''}" data-entry="hotel:${h.id}"><button class="hotel-image" data-action="detail" data-key="hotel:${h.id}" aria-label="${esc(h.name)} 객실·사진·후기 보기">${cover(h)?`<img src="${esc(cover(h))}" alt="${esc(h.name)} 소개 사진" width="600" height="370" loading="lazy">`:icon('bed')}<span class="photo-badge">사진 ${h.photos.length}장</span>${on?`<span class="selected-ribbon">${icon('check')}선택한 숙소</span>`:''}</button><div class="hotel-card-body"><h3>${esc(h.name)}</h3><p class="hotel-location">${esc(areaName(h))} · ${esc(h.style)}</p><div class="hotel-price"><span>3박 합계</span><strong>${won(h.price)}</strong></div><p class="night-price">2인 1실 · 1박 약 ${won(h.price/3)}</p><div class="price-conditions">${h.member?tag('회원가','warm'):''}${tag(priceCondition(h),h.unknownFees?'warm':'')}</div><p class="hotel-room">${esc(h.room)}${h.roomSize?' · '+h.roomSize+'㎡':''}<small>${esc(h.beds)}</small></p><div class="hotel-review"><strong>${h.rating.toFixed(1)}</strong><span>/ 10 · Booking.com ${h.reviewCount.toLocaleString('ko-KR')}개</span></div><dl class="hotel-scores">${[['청결','청결도'],['시설','시설'],['응대','직원 친절도']].map(([a,b])=>`<div><dt>${a}</dt><dd>${Number(h.scores[b]).toFixed(1)}</dd></div>`).join('')}</dl><p class="hotel-one-line">${esc(h.oneLine||h.note)}</p><div class="card-footer"><button class="button ${on?'is-selected':'primary'}" data-action="pick-hotel" data-id="${h.id}" aria-pressed="${on}">${on?icon('check')+'선택함':'이 숙소 선택'}</button><button class="text-button" data-action="detail" data-key="hotel:${h.id}">객실·후기</button><button class="text-button" data-action="focus-map" data-key="hotel:${h.id}">지도</button></div><label class="compare-check"><input type="checkbox" data-compare="${h.id}" ${ui.compare.includes(h.id)?'checked':''}>비교에 담기</label></div></article>`;}
